259		pod, err := driver.podForClaim(ctx, claim, podRef)
260		if err != nil {
261			return err
262		}
263	
264		// ResourceClaim generated from a ResourceClaimTemplate stores the original template name in an annotation
265		// (see https://kubernetes.io/docs/reference/labels-annotations-taints/#resource-kubernetes-io-pod-claim-name).
266		// For generated claims we need to use that name to look up the prefixes, because that's how users will specify
267		// them in the pod annotation.
268		claimName, found := annotation.Get(claim, "resource.kubernetes.io/pod-claim-name")
269		if !found {
270			claimName = claim.Name // annotation not found, it is a regular claim, use its own name to look up prefixes
271		}
272	
273		prefixes, err := addressesForClaim(pod, claimName)
274		if err != nil {
275			return err
276		}
277	
278		var errs []error
279		for request, prefix := range prefixes {
280			errs = append(errs,
281				driver.applyAddressToConfig(claim, request, prefix.IPv4, devicesCfg),
282				driver.applyAddressToConfig(claim, request, prefix.IPv6, devicesCfg),
283			)
284		}
285		return errors.Join(errs...)
286	}
